<?php
declare(strict_types=1);
require __DIR__.'/store-common.php';
$pdo=store_setup();$error='';$mode=(string)($_GET['mode']??'login');if(!in_array($mode,['login','register'],true))$mode='login';
if(!empty($_SESSION['customer_id'])&&$_SERVER['REQUEST_METHOD']!=='POST'){$mode='account';}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=(string)($_POST['action']??'login');$phone=preg_replace('/\s+/','',trim((string)($_POST['phone']??'')));$password=(string)($_POST['password']??'');$mode=$action==='register'?'register':'login';
 try{if(!preg_match('/^09[0-9]{9}$/',$phone))throw new RuntimeException('شماره موبایل باید با قالب 09xxxxxxxxx وارد شود.');
 if($action==='register'){if(strlen($password)<8)throw new RuntimeException('رمز عبور باید حداقل ۸ نویسه باشد.');$s=$pdo->prepare('INSERT INTO users(username,phone,password_hash) VALUES(?,?,?)');$s->execute(['customer-'.$phone,$phone,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();}
 else{$s=$pdo->prepare('SELECT id,password_hash FROM users WHERE phone=? LIMIT 1');$s->execute([$phone]);$u=$s->fetch();if(!$u||!password_verify($password,$u['password_hash']))throw new RuntimeException('شماره موبایل یا رمز عبور اشتباه است.');$uid=(int)$u['id'];}
 session_regenerate_id(true);$_SESSION['customer_id']=$uid;$_SESSION['customer_phone']=$phone;$next=(string)($_POST['next']??$_GET['next']??'');if($next==='checkout')go('checkout.php');notice($action==='register'?'حساب کاربری ساخته شد.':'با موفقیت وارد شدی.');go('account.php');
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'ثبت‌نام انجام نشد؛ ممکن است این شماره قبلاً ثبت شده باشد.';}
}
store_header($pdo,'حساب کاربری');
if($mode==='account'&&!empty($_SESSION['customer_id'])){echo '<section class="shop-panel"><h1>حساب کاربری</h1><p>شماره موبایل: '.e($_SESSION['customer_phone']??'').'</p><form method="post" class="shop-form"><input type="hidden" name="_csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="logout"><button class="shop-btn alt">خروج از حساب</button></form></section>';if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='logout'){$_SESSION=[];session_regenerate_id(true);go('account.php');}}
else {if($error)echo '<div class="shop-alert error">'.e($error).'</div>';echo '<section class="shop-panel"><h1>'.($mode==='register'?'ساخت حساب کاربری':'ورود به حساب کاربری').'</h1><p class="shop-muted">ورود با شماره موبایل و رمز عبور انجام می‌شود؛ پیامک لازم نیست.</p><form method="post" class="shop-form"><input type="hidden" name="_csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.($mode==='register'?'register':'login').'"><input type="hidden" name="next" value="'.e((string)($_GET['next']??'')).'"><label>شماره موبایل<input name="phone" inputmode="numeric" autocomplete="tel" placeholder="09123456789" pattern="09[0-9]{9}" maxlength="11" required></label><label>رمز عبور<input type="password" name="password" minlength="'.($mode==='register'?'8':'1').'" autocomplete="'.($mode==='register'?'new-password':'current-password').'" required></label><button class="shop-btn">'.($mode==='register'?'ساخت حساب':'ورود').'</button></form><p class="shop-muted">'.($mode==='register'?'قبلاً حساب ساخته‌ای؟ <a href="account.php?mode=login">ورود</a>':'حساب نداری؟ <a href="account.php?mode=register'.(!empty($_GET['next'])?'&next=checkout':'').'">ثبت‌نام</a>').'</p></section>';}
store_footer();
